mod common;

use axum::http::{Method, StatusCode};
use axum_bookclub::app;
use common::send;
use serde_json::json;

async fn make_club(router: &axum::Router) -> u64 {
    let (_, body) = send(
        router,
        Method::POST,
        "/api/clubs",
        Some(json!({"name": "Club", "description": "x"})),
    )
    .await;
    body["id"].as_u64().unwrap()
}

#[tokio::test]
async fn create_book_defaults_to_read_and_updates_status() {
    let router = app();
    let club_id = make_club(&router).await;

    let (status, book) = send(
        &router,
        Method::POST,
        &format!("/api/clubs/{club_id}/books"),
        Some(json!({"title": "Dune", "author": "Herbert"})),
    )
    .await;
    assert_eq!(status, StatusCode::CREATED);
    assert_eq!(book["status"], "to_read");

    let book_id = book["id"].as_u64().unwrap();
    let (status, updated) = send(
        &router,
        Method::PATCH,
        &format!("/api/books/{book_id}"),
        Some(json!({"status": "reading"})),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(updated["status"], "reading");

    let (status, _) = send(
        &router,
        Method::PATCH,
        &format!("/api/books/{book_id}"),
        Some(json!({"status": "bogus"})),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);
}

#[tokio::test]
async fn list_books_pagination_composes_with_status_filter() {
    let router = app();
    let club_id = make_club(&router).await;

    // 5 'to_read', 5 'reading'
    for i in 0..5 {
        send(
            &router,
            Method::POST,
            &format!("/api/clubs/{club_id}/books"),
            Some(json!({"title": format!("tr{i}"), "author": "x"})),
        )
        .await;
    }
    for i in 0..5 {
        let (_, book) = send(
            &router,
            Method::POST,
            &format!("/api/clubs/{club_id}/books"),
            Some(json!({"title": format!("r{i}"), "author": "x"})),
        )
        .await;
        let id = book["id"].as_u64().unwrap();
        send(
            &router,
            Method::PATCH,
            &format!("/api/books/{id}"),
            Some(json!({"status": "reading"})),
        )
        .await;
    }

    let (status, page1) = send(
        &router,
        Method::GET,
        &format!("/api/clubs/{club_id}/books?status=reading&page=1&page_size=2"),
        None,
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(page1["total"].as_u64().unwrap(), 5, "total must reflect the FILTERED count");
    assert_eq!(page1["books"].as_array().unwrap().len(), 2);
    for b in page1["books"].as_array().unwrap() {
        assert_eq!(b["status"], "reading");
    }

    let (_, page3) = send(
        &router,
        Method::GET,
        &format!("/api/clubs/{club_id}/books?status=reading&page=3&page_size=2"),
        None,
    )
    .await;
    assert_eq!(page3["books"].as_array().unwrap().len(), 1, "page 3 of 5 filtered items at size 2");
}

